def line_subtotal(qty, price):
    return qty * price


def _sum_lines(lines):
    return sum(line_subtotal(qty, price) for qty, price in lines)


def _apply_tax(subtotal, tax_rate):
    return subtotal + subtotal * tax_rate


def invoice_total(lines, tax_rate):
    subtotal = _sum_lines(lines)
    taxed = _apply_tax(subtotal, tax_rate)
    return _apply_tax(taxed, tax_rate)

